/**
 * The C runtime prelude is emitted before every generated translation unit.
 * It contains only the small, stable surface that the Kix standard library
 * relies on. Everything here is namespaced with `kix_` to avoid colliding with
 * user code.
 */
export const C_RUNTIME_PRELUDE = String.raw`/* -------------------------------------------------------------------------
 * Kix Stage 0 runtime prelude
 * Generated by kixt. This file is a single, self-contained C11 translation unit.
 * ------------------------------------------------------------------------- */
#ifndef KIX_RUNTIME_PRELUDE
#define KIX_RUNTIME_PRELUDE

#include <pthread.h>
#include <setjmp.h>
#include <stdarg.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef int64_t  kix_int;
typedef double   kix_float;
typedef bool     kix_bool;
typedef char     kix_char;

/* ---- garbage collector ------------------------------------------------- */

typedef struct KixTypeDesc KixTypeDesc;

typedef struct KixFieldDesc {
    size_t offset;
    const KixTypeDesc *desc;
} KixFieldDesc;

struct KixTypeDesc {
    int kind;
    size_t stride;
    const KixTypeDesc *element;
    const KixFieldDesc *fields;
    size_t field_count;
    void (*finalize)(void *);
    const void *vtable;
    const char *name;
    const KixTypeDesc *parent;
    const KixTypeDesc *const *interfaces;
    size_t interface_count;
};

enum {
    KIX_DESC_NONE = 0,
    KIX_DESC_CLASS = 1,
    KIX_DESC_ARRAY = 2,
    KIX_DESC_INTERFACE = 3,
    KIX_DESC_STRUCT = 4,
};

#define KIX_GC_MAGIC UINT64_C(0x4b495847434f424a)

typedef struct KixGcHeader {
    uint64_t magic;
    size_t size;
    const KixTypeDesc *desc;
    struct KixGcHeader *next;
    uint32_t mark;
    uint32_t flags;
} KixGcHeader;

#define KIX_GC_FINALIZING 1u
#define KIX_GC_FINALIZED  2u

typedef struct KixArrayRef {
    void *data;
    kix_bool managed;
} KixArrayRef;

typedef struct KixInterfaceBox {
    void *object;
    const void *vtable;
    const KixTypeDesc *object_desc;
} KixInterfaceBox;

typedef struct KixRoot {
    const KixTypeDesc *desc;
    void *slot;
} KixRoot;

static KixGcHeader *kix_gc_objects = NULL;
static size_t kix_gc_bytes = 0;
static size_t kix_gc_threshold = 4 * 1024 * 1024;
static int kix_gc_running = 0;
static _Atomic int kix_gc_tasks_active = 0;
static pthread_mutex_t kix_gc_alloc_mutex = PTHREAD_MUTEX_INITIALIZER;
static int kix_gc_stress = 0;
static int kix_gc_settings_loaded = 0;

static KixGcHeader **kix_mark_stack = NULL;
static size_t kix_mark_count = 0;
static size_t kix_mark_capacity = 0;

static KixGcHeader **kix_finalizer_queue = NULL;
static size_t kix_finalizer_count = 0;
static size_t kix_finalizer_capacity = 0;

static _Thread_local KixRoot *kix_roots = NULL;
static _Thread_local size_t kix_root_count = 0;
static _Thread_local size_t kix_root_capacity = 0;
static _Thread_local int kix_gc_pause_depth = 0;
static _Thread_local void *kix_exception_value = NULL;
static _Thread_local const KixTypeDesc *kix_exception_desc = NULL;

static size_t kix_root_mark(void) {
    return kix_root_count;
}

static void kix_root_restore(size_t mark) {
    if (mark < kix_root_count) kix_root_count = mark;
}

static void kix_root_push(const KixTypeDesc *desc, void *slot) {
    if (kix_root_count == kix_root_capacity) {
        size_t next = kix_root_capacity < 64 ? 64 : kix_root_capacity * 2;
        KixRoot *fresh = (KixRoot *)realloc(kix_roots, next * sizeof(KixRoot));
        if (!fresh) {
            fputs("kix: out of memory growing root stack\n", stderr);
            exit(1);
        }
        kix_roots = fresh;
        kix_root_capacity = next;
    }
    kix_roots[kix_root_count].desc = desc;
    kix_roots[kix_root_count].slot = slot;
    kix_root_count = kix_root_count + 1;
}

static inline kix_bool kix_gc_pause(void) {
    kix_gc_pause_depth = kix_gc_pause_depth + 1;
    return true;
}

static inline kix_bool kix_gc_resume(void) {
    if (kix_gc_pause_depth > 0) kix_gc_pause_depth = kix_gc_pause_depth - 1;
    return true;
}

static void *kix_gc_alloc(size_t size, const KixTypeDesc *desc) {
    size_t total = sizeof(KixGcHeader) + (size > 0 ? size : 1);
    KixGcHeader *header = (KixGcHeader *)calloc(1, total);
    if (!header) {
        fputs("kix: out of memory allocating managed object\n", stderr);
        exit(1);
    }
    header->magic = KIX_GC_MAGIC;
    header->size = size;
    header->desc = desc;

    pthread_mutex_lock(&kix_gc_alloc_mutex);
    header->next = kix_gc_objects;
    kix_gc_objects = header;
    kix_gc_bytes = kix_gc_bytes + size;
    pthread_mutex_unlock(&kix_gc_alloc_mutex);
    return (void *)(header + 1);
}

static void kix_gc_mark_object(KixGcHeader *header) {
    if (!header || header->magic != KIX_GC_MAGIC || header->mark) return;
    header->mark = 1;

    if (kix_mark_count == kix_mark_capacity) {
        size_t next = kix_mark_capacity < 128 ? 128 : kix_mark_capacity * 2;
        KixGcHeader **fresh =
            (KixGcHeader **)realloc(kix_mark_stack, next * sizeof(KixGcHeader *));
        if (!fresh) {
            fputs("kix: out of memory growing mark stack\n", stderr);
            exit(1);
        }
        kix_mark_stack = fresh;
        kix_mark_capacity = next;
    }
    kix_mark_stack[kix_mark_count] = header;
    kix_mark_count = kix_mark_count + 1;
}

static void kix_gc_trace_value(const KixTypeDesc *desc, void *slot) {
    if (!desc || !slot) return;

    if (desc->kind == KIX_DESC_CLASS) {
        void *pointer = *(void **)slot;
        if (!pointer) return;
        kix_gc_mark_object(((KixGcHeader *)pointer) - 1);
        return;
    }

    if (desc->kind == KIX_DESC_ARRAY) {
        KixArrayRef *reference = (KixArrayRef *)slot;
        if (!reference->managed || !reference->data) return;
        kix_gc_mark_object(((KixGcHeader *)reference->data) - 1);
        return;
    }

    if (desc->kind == KIX_DESC_INTERFACE) {
        void *pointer = *(void **)slot;
        if (!pointer) return;
        kix_gc_mark_object(((KixGcHeader *)pointer) - 1);
        return;
    }

    if (desc->kind == KIX_DESC_STRUCT) {
        size_t i = 0;
        while (i < desc->field_count) {
            const KixFieldDesc *field = &desc->fields[i];
            kix_gc_trace_value(field->desc, (char *)slot + field->offset);
            i = i + 1;
        }
    }
}

static void kix_gc_process_marks(void) {
    while (kix_mark_count > 0) {
        kix_mark_count = kix_mark_count - 1;
        KixGcHeader *header = kix_mark_stack[kix_mark_count];
        const KixTypeDesc *desc = header->desc;
        if (!desc) continue;

        char *base = (char *)(header + 1);
        if (desc->kind == KIX_DESC_CLASS) {
            size_t i = 0;
            while (i < desc->field_count) {
                const KixFieldDesc *field = &desc->fields[i];
                kix_gc_trace_value(field->desc, base + field->offset);
                i = i + 1;
            }
        } else if (desc->kind == KIX_DESC_ARRAY) {
            const KixTypeDesc *element = desc->element;
            if (
                element &&
                (element->kind == KIX_DESC_CLASS ||
                 element->kind == KIX_DESC_INTERFACE ||
                 element->kind == KIX_DESC_STRUCT)
            ) {
                size_t offset = 0;
                while (offset + desc->stride <= header->size) {
                    kix_gc_trace_value(element, base + offset);
                    offset = offset + desc->stride;
                }
            }
        } else if (desc->kind == KIX_DESC_INTERFACE) {
            KixInterfaceBox *box = (KixInterfaceBox *)base;
            if (box->object && box->object_desc) {
                if (box->object_desc->kind == KIX_DESC_STRUCT) {
                    kix_gc_mark_object(((KixGcHeader *)box->object) - 1);
                } else {
                    kix_gc_trace_value(box->object_desc, &box->object);
                }
            }
        } else if (desc->kind == KIX_DESC_STRUCT) {
            size_t i = 0;
            while (i < desc->field_count) {
                const KixFieldDesc *field = &desc->fields[i];
                kix_gc_trace_value(field->desc, base + field->offset);
                i = i + 1;
            }
        }
    }
}

static void kix_gc_queue_finalizer(KixGcHeader *header) {
    if (kix_finalizer_count == kix_finalizer_capacity) {
        size_t next =
            kix_finalizer_capacity < 64 ? 64 : kix_finalizer_capacity * 2;
        KixGcHeader **fresh = (KixGcHeader **)realloc(
            kix_finalizer_queue, next * sizeof(KixGcHeader *));
        if (!fresh) {
            fputs("kix: out of memory growing finalizer queue\n", stderr);
            exit(1);
        }
        kix_finalizer_queue = fresh;
        kix_finalizer_capacity = next;
    }
    kix_finalizer_queue[kix_finalizer_count] = header;
    kix_finalizer_count = kix_finalizer_count + 1;
}

static void kix_gc_trace_task_roots(void);

static void kix_gc_collect(void) {
    if (kix_gc_running) return;
    kix_gc_running = 1;

    KixGcHeader *header = kix_gc_objects;
    while (header) {
        header->mark = 0;
        header = header->next;
    }
    kix_mark_count = 0;

    size_t i = 0;
    while (i < kix_root_count) {
        kix_gc_trace_value(kix_roots[i].desc, kix_roots[i].slot);
        i = i + 1;
    }
    if (kix_exception_value && kix_exception_desc) {
        kix_gc_trace_value(kix_exception_desc, &kix_exception_value);
    }
    kix_gc_trace_task_roots();
    kix_gc_process_marks();

    KixGcHeader **link = &kix_gc_objects;
    while (*link) {
        header = *link;
        if (!header->mark) {
            if (
                header->desc &&
                header->desc->finalize &&
                (header->flags & KIX_GC_FINALIZED) == 0
            ) {
                header->mark = 1;
                kix_gc_queue_finalizer(header);
                link = &header->next;
            } else {
                *link = header->next;
                kix_gc_bytes = kix_gc_bytes - header->size;
                free(header);
            }
        } else {
            header->mark = 0;
            link = &header->next;
        }
    }

    size_t finalizerIndex = 0;
    while (finalizerIndex < kix_finalizer_count) {
        header = kix_finalizer_queue[finalizerIndex];
        finalizerIndex = finalizerIndex + 1;
        if (header->desc && header->desc->finalize) {
            header->flags = header->flags | KIX_GC_FINALIZING;
            header->desc->finalize((void *)(header + 1));
            header->flags = header->flags & ~KIX_GC_FINALIZING;
            header->flags = header->flags | KIX_GC_FINALIZED;
        }
        header->mark = 0;
    }
    kix_finalizer_count = 0;

    kix_gc_threshold = kix_gc_bytes * 2;
    if (kix_gc_threshold < 4 * 1024 * 1024) {
        kix_gc_threshold = 4 * 1024 * 1024;
    }
    if (getenv("KIX_GC_LOG")) {
        fprintf(stderr, "kix gc: live bytes=%zu\n", kix_gc_bytes);
    }
    kix_gc_running = 0;
}

static void kix_gc_safepoint(void) {
    if (!kix_gc_settings_loaded) {
        kix_gc_settings_loaded = 1;
        const char *stress = getenv("KIX_GC_STRESS");
        if (stress && *stress) kix_gc_stress = 1;
        const char *threshold = getenv("KIX_GC_THRESHOLD");
        if (threshold && *threshold) {
            long value = strtol(threshold, NULL, 10);
            if (value > 0) kix_gc_threshold = (size_t)value;
        }
    }
    if (kix_gc_pause_depth > 0 || kix_gc_running) return;
    if (atomic_load(&kix_gc_tasks_active) > 0) return;
    if (kix_gc_stress || kix_gc_bytes >= kix_gc_threshold) kix_gc_collect();
}

static inline void *kix_object_alloc(size_t size, const KixTypeDesc *desc) {
    return kix_gc_alloc(size, desc);
}

static inline void *kix_struct_box(
    void *value,
    size_t size,
    const KixTypeDesc *struct_desc
) {
    void *box = kix_gc_alloc(size, struct_desc);
    memcpy(box, value, size);
    return box;
}

static inline void *kix_iface_new(
    void *object,
    const void *vtable,
    const KixTypeDesc *object_desc,
    const KixTypeDesc *iface_desc
) {
    if (!object) return NULL;
    KixInterfaceBox *box = (KixInterfaceBox *)kix_gc_alloc(
        sizeof(KixInterfaceBox), iface_desc);
    box->object = object;
    box->vtable = vtable;
    box->object_desc = object_desc;
    return box;
}

/* ---- exceptions -------------------------------------------------------- */

typedef struct KixTryFrame {
    jmp_buf env;
    struct KixTryFrame *previous;
    size_t root_mark;
} KixTryFrame;

static _Thread_local KixTryFrame *kix_try_top = NULL;

static void kix_throw(void *value, const KixTypeDesc *desc) {
    if (!value) {
        fputs("kix: cannot throw null\n", stderr);
        exit(1);
    }
    kix_exception_value = value;
    kix_exception_desc = desc;

    if (!kix_try_top) {
        fputs("kix: uncaught exception\n", stderr);
        exit(1);
    }

    kix_root_restore(kix_try_top->root_mark);
    longjmp(kix_try_top->env, 1);
}

static void *kix_exception_take(void) {
    void *value = kix_exception_value;
    kix_exception_value = NULL;
    kix_exception_desc = NULL;
    return value;
}

static void kix_exception_take_full(void **value, const KixTypeDesc **desc) {
    if (value) *value = kix_exception_value;
    if (desc) *desc = kix_exception_desc;
    kix_exception_value = NULL;
    kix_exception_desc = NULL;
}

static void kix_rethrow(void) {
    kix_throw(kix_exception_value, kix_exception_desc);
}

static inline const KixTypeDesc *kix_object_type(void *pointer) {
    if (!pointer) return NULL;
    return (((KixGcHeader *)pointer) - 1)->desc;
}

static inline const KixTypeDesc *kix_interface_type(void *pointer) {
    if (!pointer) return NULL;
    return ((KixInterfaceBox *)pointer)->object_desc;
}

static inline void *kix_interface_object(void *pointer) {
    if (!pointer) return NULL;
    return ((KixInterfaceBox *)pointer)->object;
}

static kix_bool kix_is_type(const KixTypeDesc *actual, const KixTypeDesc *target) {
    if (!actual || !target) return false;
    const KixTypeDesc *current = actual;
    while (current) {
        if (current == target) return true;
        size_t i = 0;
        while (i < current->interface_count) {
            if (current->interfaces[i] == target) return true;
            i = i + 1;
        }
        current = current->parent;
    }
    return false;
}

static void *kix_checked_cast(
    void *value,
    const KixTypeDesc *actual,
    const KixTypeDesc *target,
    const char *what
) {
    if (!value) return NULL;
    if (!kix_is_type(actual, target)) {
        fprintf(stderr, "kix: invalid cast to %s\n", what);
        exit(1);
    }
    return value;
}

static void *kix_interface_downcast(
    void *iface,
    const KixTypeDesc *target,
    const char *what
) {
    if (!iface) return NULL;
    KixInterfaceBox *box = (KixInterfaceBox *)iface;
    return kix_checked_cast(box->object, box->object_desc, target, what);
}

static inline void *kix_interface_as(
    void *iface,
    const KixTypeDesc *target,
    const char *what
) {
    if (!iface) return NULL;
    KixInterfaceBox *box = (KixInterfaceBox *)iface;
    if (!kix_is_type(box->object_desc, target)) {
        fprintf(stderr, "kix: invalid interface cast to %s\n", what);
        exit(1);
    }
    return iface;
}

static inline const void *kix_class_vtable(void *pointer) {
    KixGcHeader *header = ((KixGcHeader *)pointer) - 1;
    return header->desc ? header->desc->vtable : NULL;
}

static inline kix_int kix_bounds_check(kix_int index, kix_int length) {
    if (index < 0 || index >= length) {
        fprintf(stderr, "kix: index %lld out of bounds for length %lld\n",
                (long long)index, (long long)length);
        exit(1);
    }
    return index;
}

static inline void *kix_null_check(void *pointer, const char *what) {
    if (!pointer) {
        fprintf(stderr, "kix: %s is null\n", what);
        exit(1);
    }
    return pointer;
}

static inline void *kix_class_check(void *pointer, const char *what) {
    if (!pointer) {
        fprintf(stderr, "kix: %s is null\n", what);
        exit(1);
    }
    KixGcHeader *header = ((KixGcHeader *)pointer) - 1;
    if (header->magic != KIX_GC_MAGIC) {
        fprintf(stderr, "kix: %s is not a managed class object\n", what);
        exit(1);
    }
    if (header->flags & KIX_GC_FINALIZED) {
        fprintf(stderr, "kix: %s was already destroyed\n", what);
        exit(1);
    }
    return pointer;
}

static void kix_delete(void *pointer) {
    if (!pointer) return;
    KixGcHeader *header = ((KixGcHeader *)pointer) - 1;
    if (header->magic != KIX_GC_MAGIC) {
        fputs("kix: delete requires a managed class object\n", stderr);
        exit(1);
    }
    if (header->flags & (KIX_GC_FINALIZING | KIX_GC_FINALIZED)) return;
    header->flags = header->flags | KIX_GC_FINALIZING;
    if (header->desc && header->desc->finalize) {
        header->desc->finalize(pointer);
    }
    header->flags = header->flags & ~KIX_GC_FINALIZING;
    header->flags = header->flags | KIX_GC_FINALIZED;
}

/* ---- synchronization bridge ------------------------------------------- */

static kix_int kix_sync_mutex_create(void) {
    pthread_mutex_t *mutex = (pthread_mutex_t *)calloc(1, sizeof(pthread_mutex_t));
    if (!mutex) {
        fputs("kix: out of memory creating mutex\n", stderr);
        exit(1);
    }
    pthread_mutex_init(mutex, NULL);
    return (kix_int)(intptr_t)mutex;
}

static void kix_sync_mutex_lock(kix_int handle) {
    if (handle) pthread_mutex_lock((pthread_mutex_t *)(intptr_t)handle);
}

static void kix_sync_mutex_unlock(kix_int handle) {
    if (handle) pthread_mutex_unlock((pthread_mutex_t *)(intptr_t)handle);
}

static void kix_sync_mutex_destroy(kix_int handle) {
    if (!handle) return;
    pthread_mutex_t *mutex = (pthread_mutex_t *)(intptr_t)handle;
    pthread_mutex_destroy(mutex);
    free(mutex);
}

static kix_int kix_sync_condvar_create(void) {
    pthread_cond_t *cond = (pthread_cond_t *)calloc(1, sizeof(pthread_cond_t));
    if (!cond) {
        fputs("kix: out of memory creating condition variable\n", stderr);
        exit(1);
    }
    pthread_cond_init(cond, NULL);
    return (kix_int)(intptr_t)cond;
}

static void kix_sync_condvar_wait(kix_int cond_handle, kix_int mutex_handle) {
    if (cond_handle && mutex_handle) {
        pthread_cond_wait(
            (pthread_cond_t *)(intptr_t)cond_handle,
            (pthread_mutex_t *)(intptr_t)mutex_handle);
    }
}

static void kix_sync_condvar_signal(kix_int handle) {
    if (handle) pthread_cond_signal((pthread_cond_t *)(intptr_t)handle);
}

static void kix_sync_condvar_broadcast(kix_int handle) {
    if (handle) pthread_cond_broadcast((pthread_cond_t *)(intptr_t)handle);
}

static void kix_sync_condvar_destroy(kix_int handle) {
    if (!handle) return;
    pthread_cond_t *cond = (pthread_cond_t *)(intptr_t)handle;
    pthread_cond_destroy(cond);
    free(cond);
}

/* ---- formatted output bridge ------------------------------------------- */

kix_int kix_print_format(const char *format, ...) {
    if (!format) return 0;
    va_list args;
    va_start(args, format);
    int result = vprintf(format, args);
    va_end(args);
    fflush(stdout);
    return (kix_int)result;
}

static kix_int kix_run_command(const char *command) {
    if (!command) return -1;
    return (kix_int)system(command);
}

/* ---- syscall primitive -------------------------------------------------- */

/*
 * Kix currently targets Linux. Syscall numbers live in target-specific
 * modules under modules/kix/syscalls/, while this wrapper handles the
 * architecture syscall ABI. The compiler always passes exactly six argument
 * slots, padding unused ones with zero.
 */
#if !defined(__linux__)
#error "Kix currently targets Linux"
#endif

kix_int kix_syscall(kix_int number, ...) {
    kix_int a1 = 0, a2 = 0, a3 = 0, a4 = 0, a5 = 0, a6 = 0;
    va_list args;

    va_start(args, number);
    a1 = va_arg(args, kix_int);
    a2 = va_arg(args, kix_int);
    a3 = va_arg(args, kix_int);
    a4 = va_arg(args, kix_int);
    a5 = va_arg(args, kix_int);
    a6 = va_arg(args, kix_int);
    va_end(args);

#if defined(__x86_64__)
    long result;
    register long r10 __asm__("r10") = (long)a4;
    register long r8  __asm__("r8")  = (long)a5;
    register long r9  __asm__("r9")  = (long)a6;
    __asm__ volatile (
        "syscall"
        : "=a"(result)
        : "a"((long)number), "D"((long)a1), "S"((long)a2), "d"((long)a3),
          "r"(r10), "r"(r8), "r"(r9)
        : "rcx", "r11", "memory"
    );
    return (kix_int)result;
#elif defined(__aarch64__)
    register long x8 __asm__("x8") = (long)number;
    register long x0 __asm__("x0") = (long)a1;
    register long x1 __asm__("x1") = (long)a2;
    register long x2 __asm__("x2") = (long)a3;
    register long x3 __asm__("x3") = (long)a4;
    register long x4 __asm__("x4") = (long)a5;
    register long x5 __asm__("x5") = (long)a6;
    __asm__ volatile (
        "svc 0"
        : "+r"(x0)
        : "r"(x8), "r"(x1), "r"(x2), "r"(x3), "r"(x4), "r"(x5)
        : "memory"
    );
    return (kix_int)x0;
#elif defined(__riscv)
    register long a7 __asm__("a7") = (long)number;
    register long a0 __asm__("a0") = (long)a1;
    register long r_a1 __asm__("a1") = (long)a2;
    register long r_a2 __asm__("a2") = (long)a3;
    register long r_a3 __asm__("a3") = (long)a4;
    register long r_a4 __asm__("a4") = (long)a5;
    register long r_a5 __asm__("a5") = (long)a6;
    __asm__ volatile (
        "ecall"
        : "+r"(a0)
        : "r"(a7), "r"(r_a1), "r"(r_a2), "r"(r_a3), "r"(r_a4), "r"(r_a5)
        : "memory"
    );
    return (kix_int)a0;
#else
#error "Kix supports Linux x86_64, aarch64, and riscv64"
#endif
}

/* ---- task system ------------------------------------------------------- */

/*
 * A task is submitted to a worker pool and runs on a worker thread. Every
 * worker owns a FIFO queue. Tasks are distributed round-robin across the
 * workers of their pool. A task's result lives in a heap buffer until the
 * process exits, so awaiting the same task twice is safe.
 */

typedef void (*KixTaskRun)(void *payload, void *result);

typedef struct KixTask {
    KixTaskRun run;
    void *payload;
    void *result;
    size_t result_size;
    const KixTypeDesc *result_desc;
    void *exception;
    const KixTypeDesc *exception_desc;
    struct KixTask *next_all;
    _Atomic kix_bool done;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} KixTask;

typedef struct KixTaskNode {
    KixTask *task;
    struct KixTaskNode *next;
} KixTaskNode;

typedef struct KixWorker {
    pthread_t thread;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    KixTaskNode *head;
    KixTaskNode *tail;
    kix_bool stop;
} KixWorker;

typedef struct KixPool {
    KixWorker *workers;
    int count;
    _Atomic int next;
} KixPool;

static pthread_mutex_t kix_pending_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t kix_pending_cond = PTHREAD_COND_INITIALIZER;
static int kix_pending_tasks = 0;
static pthread_mutex_t kix_task_list_mutex = PTHREAD_MUTEX_INITIALIZER;
static KixTask *kix_all_tasks = NULL;

static void kix_gc_trace_task_roots(void) {
    pthread_mutex_lock(&kix_task_list_mutex);
    KixTask *task = kix_all_tasks;
    while (task) {
        if (task->result && task->result_desc && atomic_load(&task->done)) {
            kix_gc_trace_value(task->result_desc, task->result);
        }
        if (task->exception && task->exception_desc) {
            kix_gc_trace_value(task->exception_desc, &task->exception);
        }
        task = task->next_all;
    }
    pthread_mutex_unlock(&kix_task_list_mutex);
}

static void *kix_worker_main(void *argument) {
    KixWorker *worker = (KixWorker *)argument;

    for (;;) {
        pthread_mutex_lock(&worker->mutex);
        while (worker->head == NULL && !worker->stop) {
            pthread_cond_wait(&worker->cond, &worker->mutex);
        }
        if (worker->head == NULL && worker->stop) {
            pthread_mutex_unlock(&worker->mutex);
            break;
        }

        KixTaskNode *node = worker->head;
        worker->head = node->next;
        if (worker->head == NULL) worker->tail = NULL;
        pthread_mutex_unlock(&worker->mutex);

        KixTask *task = node->task;
        free(node);

        KixTryFrame frame;
        frame.previous = kix_try_top;
        frame.root_mark = kix_root_mark();
        kix_try_top = &frame;
        if (setjmp(frame.env) == 0) {
            task->run(task->payload, task->result);
        } else {
            void *value = NULL;
            const KixTypeDesc *desc = NULL;
            kix_exception_take_full(&value, &desc);
            task->exception = value;
            task->exception_desc = desc;
        }
        kix_try_top = frame.previous;
        kix_root_restore(frame.root_mark);

        free(task->payload);
        task->payload = NULL;

        pthread_mutex_lock(&task->mutex);
        atomic_store(&task->done, true);
        pthread_cond_broadcast(&task->cond);
        pthread_mutex_unlock(&task->mutex);

        atomic_fetch_sub(&kix_gc_tasks_active, 1);
        pthread_mutex_lock(&kix_pending_mutex);
        kix_pending_tasks = kix_pending_tasks - 1;
        if (kix_pending_tasks == 0) pthread_cond_broadcast(&kix_pending_cond);
        pthread_mutex_unlock(&kix_pending_mutex);
    }

    return NULL;
}

static KixPool *kix_pool_create(int count) {
    if (count < 1) count = 1;

    KixPool *pool = (KixPool *)calloc(1, sizeof(KixPool));
    if (!pool) {
        fputs("kix: out of memory creating worker pool\n", stderr);
        exit(1);
    }

    pool->workers = (KixWorker *)calloc((size_t)count, sizeof(KixWorker));
    if (!pool->workers) {
        fputs("kix: out of memory creating workers\n", stderr);
        exit(1);
    }
    pool->count = count;
    atomic_init(&pool->next, 0);

    for (int i = 0; i < count; i = i + 1) {
        KixWorker *worker = &pool->workers[i];
        worker->head = NULL;
        worker->tail = NULL;
        worker->stop = false;
        pthread_mutex_init(&worker->mutex, NULL);
        pthread_cond_init(&worker->cond, NULL);
        pthread_create(&worker->thread, NULL, kix_worker_main, worker);
    }

    return pool;
}

static void kix_pool_enqueue(KixPool *pool, KixTask *task) {
    int index = atomic_fetch_add(&pool->next, 1) % pool->count;
    KixWorker *worker = &pool->workers[index];

    KixTaskNode *node = (KixTaskNode *)malloc(sizeof(KixTaskNode));
    if (!node) {
        fputs("kix: out of memory enqueueing task\n", stderr);
        exit(1);
    }
    node->task = task;
    node->next = NULL;

    pthread_mutex_lock(&worker->mutex);
    if (worker->tail) {
        worker->tail->next = node;
    } else {
        worker->head = node;
    }
    worker->tail = node;
    pthread_cond_signal(&worker->cond);
    pthread_mutex_unlock(&worker->mutex);
}

static KixTask *kix_task_submit(
    KixPool *pool,
    KixTaskRun run,
    const void *payload,
    size_t payload_size,
    size_t result_size,
    const KixTypeDesc *result_desc
) {
    if (!pool) {
        fputs("kix: task submitted before the runtime was initialized\n", stderr);
        exit(1);
    }

    KixTask *task = (KixTask *)calloc(1, sizeof(KixTask));
    if (!task) {
        fputs("kix: out of memory creating task\n", stderr);
        exit(1);
    }

    task->run = run;
    task->payload = malloc(payload_size > 0 ? payload_size : 1);
    if (!task->payload) {
        fputs("kix: out of memory copying task payload\n", stderr);
        exit(1);
    }
    if (payload && payload_size > 0) memcpy(task->payload, payload, payload_size);

    task->result_size = result_size;
    task->result = result_size > 0 ? calloc(1, result_size) : NULL;
    task->result_desc = result_desc;
    atomic_init(&task->done, false);
    pthread_mutex_init(&task->mutex, NULL);
    pthread_cond_init(&task->cond, NULL);

    pthread_mutex_lock(&kix_pending_mutex);
    kix_pending_tasks = kix_pending_tasks + 1;
    pthread_mutex_unlock(&kix_pending_mutex);
    atomic_fetch_add(&kix_gc_tasks_active, 1);
    pthread_mutex_lock(&kix_task_list_mutex);
    task->next_all = kix_all_tasks;
    kix_all_tasks = task;
    pthread_mutex_unlock(&kix_task_list_mutex);

    kix_pool_enqueue(pool, task);
    return task;
}

/*
 * Fire-and-forget task calls may still be queued when main returns. Wait for
 * all submitted tasks before the process exits so their side effects are not
 * lost.
 */
static int kix_runtime_shutdown(void) {
    pthread_mutex_lock(&kix_pending_mutex);
    while (kix_pending_tasks > 0) {
        pthread_cond_wait(&kix_pending_cond, &kix_pending_mutex);
    }
    pthread_mutex_unlock(&kix_pending_mutex);

    int failures = 0;
    pthread_mutex_lock(&kix_task_list_mutex);
    KixTask *task = kix_all_tasks;
    while (task) {
        if (task->exception) {
            failures = failures + 1;
            fputs("kix: uncaught task exception\n", stderr);
        }
        task = task->next_all;
    }
    pthread_mutex_unlock(&kix_task_list_mutex);

    kix_gc_collect();
    return failures;
}

static void *kix_task_wait(KixTask *task) {
    if (!task) return NULL;

    pthread_mutex_lock(&task->mutex);
    while (!atomic_load(&task->done)) {
        pthread_cond_wait(&task->cond, &task->mutex);
    }
    pthread_mutex_unlock(&task->mutex);

    if (task->exception) {
        void *value = task->exception;
        const KixTypeDesc *desc = task->exception_desc;
        task->exception = NULL;
        task->exception_desc = NULL;
        kix_throw(value, desc);
    }

    return task->result;
}

static kix_bool kix_task_is_done(KixTask *task) {
    return task ? atomic_load(&task->done) : true;
}

static kix_int kix_env_int(const char *name, kix_int fallback) {
    const char *text = getenv(name);
    if (!text || !*text) return fallback;

    char *end = NULL;
    long value = strtol(text, &end, 10);
    if (end == text || value < 1) return fallback;
    return (kix_int)value;
}

#endif /* KIX_RUNTIME_PRELUDE */
`;
